// Gas mode overrides the former claim presentation; account/support/photo flows remain.
let pumpSession=null,pumpSequence=0,pumpSending=false,pumpLastTap=0,pumpLastSent=0,pumpProgress=0,pumpError='',peopleAt=Date.now(),accountAt=Date.now(),purchaseRequest=null;
const litres=n=>Math.max(0,n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
document.addEventListener('DOMContentLoaded',()=>boot(),{once:true});
function localGas(g,at){const hours=Math.max(0,now()-at)/3600000;const free=Math.max(0,(g?.free||0)-hours),paid=Math.max(0,(g?.paid||0)-hours/24);return {free,paid,total:free+paid}}
active=()=>localGas(account?.gas,accountAt).total>0;
livePeople=()=>people.map(p=>({...p,...localGas(p,peopleAt)})).filter(p=>p.total>0).sort((a,b)=>b.total-a.total||a.created-b.created||a.id.localeCompare(b.id)).map((p,i)=>({...p,rank:i+1}));
loadState=async()=>{const generation=++stateLoad,[d,a]=await Promise.all([api('/api/profiles'),session?.user?api('/api/account'):null]);if(generation!==stateLoad)return;people=d.profiles;if(typeof directoryStats!=='undefined')directoryStats=d.stats||{};peopleAt=d.serverNow;if(a){account=a;accountAt=a.serverNow;pumpProgress=a.gas.progress}};
claimCard=()=>{const g=localGas(account?.gas,accountAt);return '<section class="gas-station" id="fuel-card"><div class="station-top"><span class="eyebrow">LINKDID FILLING STATION</span><span class="station-status" id="pump-status">Ready to pump</span></div><h2>More gas.<br><span>More spotlight.</span></h2><p>Tap the pump. Build your balance. Climb the leaderboard.</p><div class="station-display"><span>YOUR TOTAL GAS</span><strong id="gas-total">'+litres(g.total)+' <small>L</small></strong><div class="station-mini"><span>Rank <b data-own-rank>'+(account?.rank?'#'+account.rank:'—')+'</b></span><span>Highest balance ranks first</span></div></div><div class="tank-pair"><div class="mini-tank"><span>FREE GAS</span><strong id="gas-free">'+litres(g.free)+' L</strong><small>Uses 1 L / hour</small></div><div class="mini-tank paid-tank"><span>PAID GAS</span><strong id="gas-paid">'+litres(g.paid)+' L</strong><small>Uses 1 L / 24 hours</small></div></div><div class="pump-zone"><div class="earned-float" id="earned-float" aria-live="polite"></div><button class="pump-trigger" id="pump-trigger" data-fill aria-label="Tap the gas pump to earn free gas"><span class="pump-glyph" aria-hidden="true">⛽</span><span>Tap to pump</span><small>Keep clicking for free gas</small></button><div class="pump-progress-head"><span>Next free litre</span><b id="pump-seconds">'+Math.floor(pumpProgress/1000)+' / 60 sec</b></div><div class="pump-progress" role="progressbar" aria-label="Active pumping toward your next litre" aria-valuemin="0" aria-valuemax="60" aria-valuenow="'+Math.floor(pumpProgress/1000)+'"><div id="pump-progress-fill" style="width:'+(pumpProgress/600)+'%"></div></div><p class="pump-hint">1 minute of active clicking = 1 L.<br>Tap at least once every 3 seconds. Breaks pause your progress.</p><p id="pump-error" class="claim-error" role="alert">'+esc(pumpError)+'</p></div><a class="buy-gas-button" href="/billing"><span>Skip the clicks. Buy gas.</span><b>$1 / L →</b></a><p class="station-footnote">Both tanks drain while you’re away. Your paid gas lasts 24× longer per litre.</p></section>'};
fill=async()=>{if(!session?.user){location.href='/account';return}if(!account?.profile){if($('#profile-form')){$('#profile-form').scrollIntoView({behavior:'smooth',block:'center'});$('#profile-form').elements.name.focus();toast('Save your profile to start pumping.')}else location.href='/account?pump=1';return}pumpLastTap=performance.now();pumpError='';const button=$('#pump-trigger');if(button){button.classList.remove('pump-tap');void button.offsetWidth;button.classList.add('pump-tap')}if(!pumpSession&&!pumpSending){pumpSending=true;try{const d=await api('/api/gas/start',{});pumpSession=d.session;pumpSequence=d.gas.sequence;account.gas=d.gas;accountAt=d.serverNow;pumpProgress=d.gas.progress;pumpLastSent=performance.now()}catch(e){pumpError=e.message}finally{pumpSending=false;tick()}}};
async function pumpPulse(){if(!pumpSession||pumpSending||document.visibilityState==='hidden'||performance.now()-pumpLastTap>2800||performance.now()-pumpLastSent<2900)return;pumpSending=true;pumpLastSent=performance.now();try{const previous=account?.gas?.progress||0,d=await api('/api/gas/pulse',{session:pumpSession,sequence:pumpSequence+1});pumpSequence=d.gas.sequence;pumpProgress=d.gas.progress;account.gas=d.gas;accountAt=d.serverNow;if(d.earned>0){const f=$('#earned-float');if(f){f.textContent='+1 L free gas';f.classList.remove('earned-show');void f.offsetWidth;f.classList.add('earned-show')}toast('1 litre earned! Your free tank is filling.');await loadState();rows()}}catch(e){pumpError=e.message;pumpSession=null}finally{pumpSending=false;tick()}}
setInterval(pumpPulse,500);
tick=()=>{const g=localGas(account?.gas,accountAt);for(const [id,v] of [['gas-total',litres(g.total)+' <small>L</small>'],['gas-free',litres(g.free)+' L'],['gas-paid',litres(g.paid)+' L']])if($('#'+id))$('#'+id).innerHTML=v;const pumping=pumpSession&&performance.now()-pumpLastTap<3000&&document.visibilityState!=='hidden';if($('#pump-status')){$('#pump-status').textContent=pumping?'Pumping…':pumpProgress?'Progress paused':'Ready to pump';$('#pump-status').classList.toggle('pumping',!!pumping)}if($('#pump-trigger'))$('#pump-trigger').classList.toggle('is-pumping',!!pumping);if($('#pump-seconds'))$('#pump-seconds').textContent=(pumpProgress/1000).toFixed(1)+' / 60 sec';if($('#pump-progress-fill')){$('#pump-progress-fill').style.width=pumpProgress/600+'%';$('.pump-progress').setAttribute('aria-valuenow',String(pumpProgress/1000))}if($('#pump-error'))$('#pump-error').textContent=pumpError;const own=livePeople().find(p=>p.id===account?.profile?.id);if($('[data-own-rank]'))$('[data-own-rank]').textContent=own?'#'+own.rank:account?.rank?'#'+account.rank:'—';document.querySelectorAll('[data-gas-free]').forEach(x=>{const at=Number(x.dataset.gasAt),v=localGas({free:Number(x.dataset.gasFree),paid:Number(x.dataset.gasPaid)},at);x.textContent=litres(v.total)+' L'})};
updateFuel=()=>{tick()};
const claimRefresh=refresh;
refresh=async(manual=false)=>{if(pumpSending||performance.now()-pumpLastTap<3500)return;await claimRefresh(manual)};
rows=()=>{if(!$('#profiles'))return;const all=livePeople(),list=all.filter(p=>(filter==='All people'||p.category===filter)&&(!search||(p.name+' '+p.headline+' '+p.location).toLowerCase().includes(search)));$('#count').textContent=all.length+' fuelled profiles';$('#profiles').innerHTML=list.length?list.map(p=>'<article class="profile '+(p.rank===1?'first':'')+'"><span class="rank">#'+p.rank+'</span>'+avatar(p)+'<div><div class="person-name"><a href="/profile/'+p.id+'">'+esc(p.name)+'</a></div><p class="headline">'+esc(p.headline)+'</p><div class="meta"><span class="tag">'+esc(p.category)+'</span><span>'+esc(p.location)+'</span></div></div><div class="gas-cell"><strong data-gas-free="'+p.free+'" data-gas-paid="'+p.paid+'" data-gas-at="'+now()+'">'+litres(p.total)+' L</strong><span>'+litres(p.free)+' free · '+litres(p.paid)+' paid</span><a href="/profile/'+p.id+'">View profile ↗</a></div></article>').join(''):'<div class="page-state"><h2>'+(all.length?'No matching profiles.':'Pump your way to the first spot.')+'</h2><p>Earn your first litre to enter the leaderboard.</p><button class="button dark" data-fill>Start pumping — Free</button></div>';images();document.querySelectorAll('#profiles [data-fill]').forEach(b=>b.onclick=fill)};
const originalHome=home;
home=()=>{originalHome();const hero=$('.free-hero>div');if(hero)hero.innerHTML='<span class="eyebrow">THE GAS-POWERED PROFESSIONAL LEADERBOARD</span><h1>Fuel your profile.<br><span>Rise to the top.</span></h1><p>Earn free gas by tapping the pump, or buy gas for $1 per litre. The highest remaining balance takes the top spot.</p><div class="hero-pills"><span>⛽ 60 seconds holding = 1 L</span><span>⚡ Buy gas at $1 / L</span></div><div class="gas-rules-mini"><b>Two ways to fuel. One leaderboard.</b><p>Free gas uses 1 L/hour.<br>Paid gas uses 1 L every 24 hours.<br>Ranking uses both balances together.</p></div>';const strip=$('.how-strip');if(strip)strip.innerHTML='<span><b>01</b> Create your profile</span><span><b>02</b> Pump or purchase gas</span><span><b>03</b> More gas ranks higher</span>';if($('.search-row>span'))$('.search-row>span').textContent='Highest remaining gas first';if($('.board-footer>span'))$('.board-footer>span').textContent='Total gas = free + paid balance';document.title='Linkdid — Fuel your profile';};
const originalDashboard=dashboard;
dashboard=()=>{originalDashboard();if(!session.user)return;document.querySelectorAll('.panel').forEach(p=>{if(p.querySelector('h2')?.textContent==='Claim history')p.innerHTML='<h2>Your gas balance</h2><p>Free and purchased gas are kept in separate tanks. Both start draining as soon as they are credited.</p><p><b>Free:</b> 1 minute active pumping earns 1 L. Uses 1 L/hour.</p><p><b>Paid:</b> $1 buys 1 L. Uses 1 L/24 hours.</p><p>Buy gas to add to your paid tank, or keep pumping to earn more free gas. Neither balance can go below zero.</p><a class="secondary-btn" href="/billing">Buy gas & payment history</a>'});const submit=$('#profile-form button');if(submit&&!account?.profile)submit.textContent='Save profile & start pumping';};
profilePage=async()=>{const d=await api('/api/profile/'+location.pathname.split('/')[2]),p=d.profile;document.title=p.name+' — Linkdid';shell('<section class="profile-detail"><a href="/">← Leaderboard</a><div class="panel">'+avatar(p)+'<h1>'+esc(p.name)+'</h1><p>'+esc(p.headline)+'</p><span class="tag">'+esc(p.category)+'</span><div class="profile-claim-status"><h2>'+(d.rank?'#'+d.rank+' on the leaderboard':'Tank empty · off the leaderboard')+'</h2><strong data-gas-free="'+d.gas.free+'" data-gas-paid="'+d.gas.paid+'" data-gas-at="'+d.serverNow+'">'+litres(d.gas.total)+' L</strong><p>'+litres(d.gas.free)+' L free · '+litres(d.gas.paid)+' L paid</p></div><a class="button dark" target="_blank" rel="noopener" href="/go/'+p.id+'">View on LinkedIn ↗</a><button class="secondary-btn" id="share">Copy profile link</button><p>Self-submitted profile. LinkedIn ownership is not verified.</p></div></section>');if($('#share'))$('#share').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('Profile link copied.')}catch{toast('Copy this page’s address to share.')}};if(session.user)api('/api/view/'+p.id,{}).catch(()=>{})};
about=()=>shell('<section class="account-wrap"><h1>How gas powers your spotlight.</h1><section class="panel"><h2>Pump free. Or buy your fuel.</h2><p>Press and hold the pump for 60 seconds to earn 1 litre of free gas. Release to pause. The pump stops after each litre; release and hold again for the next. Accumulated progress is saved.</p><p>Purchase gas at $1 per litre when checkout is activated. Free gas drains at 1 litre/hour; paid gas drains at 1 litre per 24 hours. Both tanks drain independently, including when you are offline.</p><p>Your remaining free and paid gas are added together. The largest total ranks first. Ties use profile creation time, then profile ID. Empty profiles leave the leaderboard but remain saved.</p><p>More purchases or pumping can improve your rank. There is no fixed 24-hour placement guarantee. This changes visibility only on Linkdid, not LinkedIn.</p><button class="button dark" data-fill>Start pumping</button></section></section>');
pastPayments=async()=>{if(!session.user){shell(login());return}const [config,d]=await Promise.all([api('/api/crypto/config'),api('/api/crypto/orders')]);shell('<section class="account-wrap"><h1>Buy gas. Stay fuelled longer.</h1><p><b>$1 per litre.</b> Your paid tank uses 1 litre every 24 hours. Both tanks count toward your total rank.</p><div class="account-grid"><section class="panel"><h2>Fill your paid tank</h2><form id="gas-purchase"><label>Litres<input name="litres" type="number" min="1" max="5000" step="1" value="5" required></label><div class="purchase-summary"><strong id="gas-price">$5</strong><span id="gas-duration">Adds 5 L · lasts 120 hours on its own</span></div>'+(config.enabled&&account?.profile?'<label>Currency & network<select name="currency">'+config.currencies.map(c=>'<option value="'+c.id+'">'+esc(c.label)+'</option>').join('')+'</select></label><label><input class="terms-box" type="checkbox" name="accepted" required> I agree to the <a target="_blank" rel="noopener" href="'+esc(config.terms)+'">purchase/refund terms</a> and paid consumption rate.</label>':'<p class="status-message">'+(!account?.profile?'Save your profile before buying gas.':'Checkout is not activated yet. You can earn free gas at the pump.')+'</p>')+'<p>Provider minimums and network fees may apply. Gas is credited after payment verification. No rank is guaranteed while payment is pending.</p><p id="buy-error" class="error-message" role="alert"></p><button class="button dark" '+(!config.enabled||!account?.profile||!config.currencies.length?'disabled':'')+'>Buy gas →</button></form></section><section class="panel"><h2>Payments & receipts</h2>'+(d.orders.map(o=>'<article class="support-item"><h3>'+(o.litres?o.litres+' L gas':'Historical placement')+' · $'+o.amount+'</h3><p>'+esc(o.status)+' · '+esc(o.network)+'</p><p>Order '+esc(o.id)+'</p>'+(o.address&&o.status==='waiting'?'<label>Send exactly<input readonly value="'+esc(o.payAmount)+' '+esc(o.currency)+'"></label><label>Address · '+esc(o.network)+'<input readonly value="'+esc(o.address)+'"></label>'+(o.extraId?'<label>Required memo / tag<input readonly value="'+esc(o.extraId)+'"></label>':'')+'<p>Use only the exact network and amount. Check status before sending; quotes can expire.</p>':'')+(o.status==='credited'?'<a href="/api/crypto/orders/'+o.id+'/receipt">Download receipt</a>':o.paymentId?'<button class="secondary-btn" data-check="'+o.id+'">Check payment & credit gas</button>':'<p>Contact support if this order needs review.</p>')+'</article>').join('')||'<p>No payments yet.</p>')+'</section></div></section>');const form=$('#gas-purchase');form.elements.litres.oninput=()=>{const l=Number(form.elements.litres.value);$('#gas-price').textContent='$'+l.toLocaleString();$('#gas-duration').textContent='Adds '+l+' L · lasts '+(l*24)+' hours on its own';purchaseRequest=null};form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;try{purchaseRequest=purchaseRequest||{id:crypto.randomUUID(),litres:Number(form.elements.litres.value),currency:form.elements.currency.value,accepted:form.elements.accepted.checked};await api('/api/crypto/orders',purchaseRequest);purchaseRequest=null;await pastPayments()}catch(e){$('#buy-error').textContent=e.message}finally{b.disabled=false}};document.querySelectorAll('[data-check]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/api/crypto/orders/'+b.dataset.check+'/check',{});await loadState();await pastPayments()}catch(e){toast(e.message)}finally{b.disabled=false}})};
